import React, { useState, useEffect } from 'react';

const FormularioCampesenaCompleto = ({ formData, setFormData, horasPrograma = 0, fechasInicio = '', fechasFin = '' }) => {
  const [instructores, setInstructores] = useState([
    {
      id: Date.now(),
      tipo: 'Técnico',
      tipo_identificacion: 'CC',
      identificacion: '',
      nombre: '',
      correo: '',
      celular: '',
      programacion: []
    }
  ]);

  useEffect(() => {
    if (typeof setFormData === 'function') {
      setFormData(prev => ({ ...prev, instructores }));
    }
  }, [instructores, setFormData]);

  const inicializarInstructor = () => ({
    id: Date.now() + Math.random(),
    tipo: 'Técnico',
    tipo_identificacion: 'CC',
    identificacion: '',
    nombre: '',
    correo: '',
    celular: '',
    programacion: []
  });

  const actualizarCampo = (id, campo, valor) => {
    setInstructores(prev => prev.map(inst => (inst.id === id ? { ...inst, [campo]: valor } : inst)));
  };

  const agregarInstructor = () => {
    setInstructores(prev => [...prev, inicializarInstructor()]);
  };

  const eliminarInstructor = (id) => {
    setInstructores(prev => prev.filter(inst => inst.id !== id));
  };

  const agregarMes = (id) => {
    setInstructores(prev => prev.map(inst => {
      if (inst.id !== id) return inst;
      const nuevo = { ...inst };
      nuevo.programacion = [...nuevo.programacion, { mes: nuevo.programacion.length + 1, rangos: [] }];
      return nuevo;
    }));
  };

  const agregarRango = (id, indexMes) => {
    setInstructores(prev => prev.map(inst => {
      if (inst.id !== id) return inst;
      const nuevo = { ...inst };
      nuevo.programacion = nuevo.programacion.map((mes, idx) => {
        if (idx !== indexMes) return mes;
        return {
          ...mes,
          rangos: [...mes.rangos, { desde: '', hasta: '', hora_inicio: '08:00', hora_fin: '16:00' }]
        };
      });
      return nuevo;
    }));
  };

  const actualizarRango = (id, indexMes, indexRango, campo, valor) => {
    setInstructores(prev => prev.map(inst => {
      if (inst.id !== id) return inst;
      const nuevo = { ...inst };
      nuevo.programacion = nuevo.programacion.map((mes, idxMes) => {
        if (idxMes !== indexMes) return mes;
        return {
          ...mes,
          rangos: mes.rangos.map((rango, idxRango) => (
            idxRango === indexRango ? { ...rango, [campo]: valor } : rango
          ))
        };
      });
      return nuevo;
    }));
  };

  const eliminarRango = (id, indexMes, indexRango) => {
    setInstructores(prev => prev.map(inst => {
      if (inst.id !== id) return inst;
      const nuevo = { ...inst };
      nuevo.programacion = nuevo.programacion.map((mes, idxMes) => {
        if (idxMes !== indexMes) return mes;
        return {
          ...mes,
          rangos: mes.rangos.filter((_, idxRango) => idxRango !== indexRango)
        };
      });
      return nuevo;
    }));
  };

  const eliminarMes = (id, indexMes) => {
    setInstructores(prev => prev.map(inst => {
      if (inst.id !== id) return inst;
      const nuevo = { ...inst };
      nuevo.programacion = nuevo.programacion
        .filter((_, idxMes) => idxMes !== indexMes)
        .map((mes, idx) => ({ ...mes, mes: idx + 1 }));
      return nuevo;
    }));
  };

  const calcularHorasInstructor = (instructor) => {
    let total = 0;
    instructor.programacion.forEach(mes => {
      mes.rangos.forEach(rango => {
        if (rango.desde && rango.hasta && rango.hora_inicio && rango.hora_fin) {
          const desde = new Date(rango.desde);
          const hasta = new Date(rango.hasta);
          const [hi, mi] = rango.hora_inicio.split(':').map(Number);
          const [hf, mf] = rango.hora_fin.split(':').map(Number);
          const minutosPorDia = (hf * 60 + mf) - (hi * 60 + mi);
          if (minutosPorDia > 0 && hasta >= desde) {
            const diffDias = Math.floor((hasta - desde) / (1000 * 60 * 60 * 24)) + 1;
            total += (minutosPorDia / 60) * diffDias;
          }
        }
      });
    });
    return total;
  };

  const validarProgramacion = () => {
    const errores = [];
    const totalHoras = instructores.reduce((sum, inst) => sum + calcularHorasInstructor(inst), 0);

    instructores.forEach((instructor, idx) => {
      if (instructor.programacion.length === 0) {
        errores.push(`Instructor ${idx + 1}: debe agregar al menos un mes de programación.`);
      }

      instructor.programacion.forEach(mes => {
        if (mes.rangos.length === 0) {
          errores.push(`Instructor ${idx + 1}, Mes ${mes.mes}: debe agregar al menos un rango.`);
        }

        mes.rangos.forEach((rango, rIdx) => {
          if (!rango.desde || !rango.hasta) {
            errores.push(`Instructor ${idx + 1}, Mes ${mes.mes}, Rango ${rIdx + 1}: fechas incompletas.`);
          }
          if (rango.desde && rango.hasta) {
            const desde = new Date(rango.desde);
            const hasta = new Date(rango.hasta);
            if (hasta < desde) {
              errores.push(`Instructor ${idx + 1}, Mes ${mes.mes}, Rango ${rIdx + 1}: hasta debe ser posterior a desde.`);
            }
          }
          if (rango.hora_inicio && rango.hora_fin) {
            const [hi, mi] = rango.hora_inicio.split(':').map(Number);
            const [hf, mf] = rango.hora_fin.split(':').map(Number);
            const inicio = hi * 60 + mi;
            const fin = hf * 60 + mf;
            if (fin <= inicio) {
              errores.push(`Instructor ${idx + 1}, Mes ${mes.mes}, Rango ${rIdx + 1}: hora fin debe ser mayor que hora inicio.`);
            }
            if (fin - inicio < 60) {
              errores.push(`Instructor ${idx + 1}, Mes ${mes.mes}, Rango ${rIdx + 1}: el rango debe durar al menos 1 hora.`);
            }
          }
        });
      });
    });

    if (Math.abs(totalHoras - horasPrograma) > 0.1) {
      errores.push(`Total de horas programadas (${totalHoras.toFixed(1)}) no coincide con el programa (${horasPrograma}).`);
    }

    return errores;
  };

  const handleValidacion = () => {
    const errores = validarProgramacion();
    if (errores.length > 0) {
      alert('Errores:\n- ' + errores.join('\n- '));
      return;
    }
    alert('Validación correcta.');
  };

  const resumenHoras = instructores.reduce((acc, inst) => {
    const horas = calcularHorasInstructor(inst);
    acc[inst.tipo] = (acc[inst.tipo] || 0) + horas;
    return acc;
  }, {});

  return (
    <div style={styles.container}>
      <h3 style={styles.title}>👨‍🏫 Instructores Campesena</h3>
      <p style={styles.subtitle}>Complete la programación de instructores según el programa.</p>

      <div style={styles.resumen}>
        <div><strong>Horas requeridas:</strong> {horasPrograma}</div>
        <div><strong>Fechas del programa:</strong> {fechasInicio || 'N/A'} - {fechasFin || 'N/A'}</div>
        {Object.entries(resumenHoras).map(([tipo, horas]) => (
          <div key={tipo}>{tipo}: {horas.toFixed(1)} h</div>
        ))}
        <div><strong>Total actual:</strong> {Object.values(resumenHoras).reduce((sum, v) => sum + v, 0).toFixed(1)} h</div>
      </div>

      {instructores.map((instructor, idx) => (
        <div key={instructor.id} style={styles.instructorBox}>
          <div style={styles.instructorHeader}>
            <h4 style={styles.instructorTitle}>Instructor {idx + 1}</h4>
            {instructores.length > 1 && (
              <button type="button" onClick={() => eliminarInstructor(instructor.id)} style={styles.removeInstructorButton}>
                ✕ Eliminar instructor
              </button>
            )}
          </div>

          <div style={styles.row}>
            <div style={styles.half}>
              <label style={styles.label}>Tipo de instructor</label>
              <select value={instructor.tipo} onChange={(e) => actualizarCampo(instructor.id, 'tipo', e.target.value)} style={styles.select}>
                <option value="Técnico">Técnico</option>
                <option value="Empresarial">Empresarial</option>
                <option value="Popular">Popular</option>
                <option value="Otro">Otro</option>
              </select>
            </div>
            <div style={styles.half}>
              <label style={styles.label}>Tipo de documento</label>
              <select value={instructor.tipo_identificacion} onChange={(e) => actualizarCampo(instructor.id, 'tipo_identificacion', e.target.value)} style={styles.select}>
                <option value="CC">CC</option>
                <option value="CE">CE</option>
                <option value="TI">TI</option>
                <option value="PAP">PAP</option>
                <option value="NIT">NIT</option>
              </select>
            </div>
          </div>

          <div style={styles.row}>
            <div style={styles.half}>
              <label style={styles.label}>Identificación</label>
              <input type="text" value={instructor.identificacion} onChange={(e) => actualizarCampo(instructor.id, 'identificacion', e.target.value)} style={styles.input} placeholder="12345678" />
            </div>
            <div style={styles.half}>
              <label style={styles.label}>Nombre completo</label>
              <input type="text" value={instructor.nombre} onChange={(e) => actualizarCampo(instructor.id, 'nombre', e.target.value)} style={styles.input} placeholder="Nombre completo" />
            </div>
          </div>

          <div style={styles.row}>
            <div style={styles.half}>
              <label style={styles.label}>Correo</label>
              <input type="email" value={instructor.correo} onChange={(e) => actualizarCampo(instructor.id, 'correo', e.target.value)} style={styles.input} placeholder="correo@ejemplo.com" />
            </div>
            <div style={styles.half}>
              <label style={styles.label}>Celular</label>
              <input type="tel" value={instructor.celular} onChange={(e) => actualizarCampo(instructor.id, 'celular', e.target.value)} style={styles.input} placeholder="3001234567" />
            </div>
          </div>

          <h5 style={styles.sectionTitle}>Programación</h5>
          {instructor.programacion.map((mes, mIdx) => (
            <div key={mIdx} style={styles.monthBox}>
              <div style={styles.monthHeader}>
                <span>Mes {mes.mes}</span>
                <button type="button" onClick={() => eliminarMes(instructor.id, mIdx)} style={styles.removeMonthButton}>Eliminar mes</button>
              </div>

              {mes.rangos.map((rango, rIdx) => (
                <div key={rIdx} style={styles.rangeBox}>
                  <div style={styles.rangeHeader}>
                    <span>Rango {rIdx + 1}</span>
                    <button type="button" onClick={() => eliminarRango(instructor.id, mIdx, rIdx)} style={styles.removeRangeButton}>✕</button>
                  </div>

                  <div style={styles.row}>
                    <div style={styles.half}>
                      <label style={styles.label}>Desde</label>
                      <input type="date" value={rango.desde} onChange={(e) => actualizarRango(instructor.id, mIdx, rIdx, 'desde', e.target.value)} style={styles.input} />
                    </div>
                    <div style={styles.half}>
                      <label style={styles.label}>Hasta</label>
                      <input type="date" value={rango.hasta} onChange={(e) => actualizarRango(instructor.id, mIdx, rIdx, 'hasta', e.target.value)} style={styles.input} />
                    </div>
                  </div>

                  <div style={styles.row}>
                    <div style={styles.half}>
                      <label style={styles.label}>Hora inicio</label>
                      <input type="time" value={rango.hora_inicio} onChange={(e) => actualizarRango(instructor.id, mIdx, rIdx, 'hora_inicio', e.target.value)} style={styles.input} />
                    </div>
                    <div style={styles.half}>
                      <label style={styles.label}>Hora fin</label>
                      <input type="time" value={rango.hora_fin} onChange={(e) => actualizarRango(instructor.id, mIdx, rIdx, 'hora_fin', e.target.value)} style={styles.input} />
                    </div>
                  </div>
                </div>
              ))}

              <button type="button" onClick={() => agregarRango(instructor.id, mIdx)} style={styles.addButton}>+ Agregar rango</button>
            </div>
          ))}

          <button type="button" onClick={() => agregarMes(instructor.id)} style={styles.addButton}>+ Agregar mes</button>
        </div>
      ))}

      <button type="button" onClick={agregarInstructor} style={styles.primaryButton}>+ Agregar instructor</button>
      <button type="button" onClick={handleValidacion} style={styles.validateButton}>Validar programación</button>
    </div>
  );
};

const styles = {
  container: { width: '100%', marginTop: '20px' },
  title: { color: '#2c3e50', marginBottom: '5px', fontSize: '20px' },
  subtitle: { color: '#7f8c8d', marginBottom: '15px', fontSize: '14px' },
  resumen: { backgroundColor: '#f8fbff', padding: '12px', borderRadius: '8px', marginBottom: '20px', border: '1px solid #cce5ff' },
