  row: { display: 'flex', gap: '12px', marginBottom: '12px', flexWrap: 'wrap' },
  half: { flex: 1, minWidth: '180px', display: 'flex', flexDirection: 'column', gap: '6px' },
  label: { fontSize: '12px', color: '#34495e', fontWeight: '600' },
  input: { padding: '9px', border: '1px solid #d1d7e0', borderRadius: '6px', fontSize: '13px' },
  select: { padding: '9px', border: '1px solid #d1d7e0', borderRadius: '6px', fontSize: '13px', backgroundColor: '#fff' },
  sectionTitle: { color: '#2c3e50', fontSize: '15px', marginBottom: '10px' },
  monthBox: { backgroundColor: '#fff', border: '1px solid #d0e7ff', borderRadius: '8px', padding: '14px', marginBottom: '12px' },
  monthHeader: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '10px' },
  removeMonthButton: { backgroundColor: '#e67e22', color: '#fff', border: 'none', borderRadius: '5px', padding: '6px 10px', cursor: 'pointer' },
  rangeBox: { backgroundColor: '#f7fbff', border: '1px solid #dbeffd', borderRadius: '8px', padding: '12px', marginBottom: '10px' },
  rangeHeader: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' },
  removeRangeButton: { backgroundColor: '#e74c3c', color: '#fff', border: 'none', borderRadius: '4px', padding: '4px 8px', cursor: 'pointer' },
  addButton: { width: '100%', padding: '10px', backgroundColor: '#3498db', color: '#fff', border: 'none', borderRadius: '6px', cursor: 'pointer', marginTop: '8px' },
  primaryButton: { width: '100%', padding: '12px', backgroundColor: '#2c82d7', color: '#fff', border: 'none', borderRadius: '8px', cursor: 'pointer', marginBottom: '12px' },
  validateButton: { width: '100%', padding: '12px', backgroundColor: '#27ae60', color: '#fff', border: 'none', borderRadius: '8px', cursor: 'pointer' }
};

export default FormularioCampesenaCompleto;
